-- Schema inicial para landing-consultora en Vercel Postgres / Neon.
-- Aplicar una vez: psql "$POSTGRES_URL" -f migrations/001_init.sql

CREATE TABLE IF NOT EXISTS leads (
  id SERIAL PRIMARY KEY,
  nombre TEXT NOT NULL,
  telefono TEXT NOT NULL,
  email TEXT NOT NULL,
  fecha TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS site_config (
  id INT PRIMARY KEY DEFAULT 1,
  business_name TEXT NOT NULL DEFAULT 'Consultoría',
  logo_url TEXT NOT NULL DEFAULT '',
  CHECK (id = 1)
);

CREATE TABLE IF NOT EXISTS site_content (
  id INT PRIMARY KEY DEFAULT 1,
  data JSONB NOT NULL,
  CHECK (id = 1)
);

INSERT INTO site_config (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

